def seed_locations(apps, schema_editor):
	Province = apps.get_model('core', 'Province')
	District = apps.get_model('core', 'District')
	Municipality = apps.get_model('core', 'Municipality')

	province_by_source_id = {}
	for row in PROVINCES:
		province, _ = Province.objects.get_or_create(name=row['name'])
		province_by_source_id[row['source_id']] = province

	district_by_source_id = {}
	for row in DISTRICTS:
		province = province_by_source_id[row['province_source_id']]
		district, _ = District.objects.get_or_create(name=row['name'], province=province)
		district_by_source_id[row['source_id']] = district

	for row in MUNICIPALITIES:
		district = district_by_source_id[row['district_source_id']]
		Municipality.objects.get_or_create(name=row['name'], district=district)


def unseed_locations(apps, schema_editor):
	Province = apps.get_model('core', 'Province')
	Municipality = apps.get_model('core', 'Municipality')
	District = apps.get_model('core', 'District')
	Municipality.objects.all().delete()
	District.objects.all().delete()
	Province.objects.all().delete()


